def flag_core_teams(apps, schema_editor):
    """
    Flag the Core Organizing Team of every organizer.

    Every organizer creation path creates the owner team in the same transaction as the organizer, with
    access to all events and the right to change teams and organizer settings. Its name is not reliable:
    it was "Administrators" before it became "Core Organizing Team", it is stored translated, and
    organizers can rename it. So the core team is the organizer's oldest team with that owner-level
    access.
    """
    Team = apps.get_model('base', 'Team')
    alias = schema_editor.connection.alias if schema_editor is not None else 'default'
    first_owner_teams = (
        Team.objects.using(alias)
        .filter(all_events=True, can_change_teams=True, can_change_organizer_settings=True)
        .values('organizer_id')
        .annotate(first_id=Min('id'))
        .values_list('first_id', flat=True)
    )
    Team.objects.using(alias).filter(id__in=list(first_owner_teams)).update(is_core_team=True)


def grant_core_team_access(apps, schema_editor):
    Team = apps.get_model('base', 'Team')
    alias = schema_editor.connection.alias if schema_editor is not None else 'default'
    core = Team.objects.using(alias).filter(is_core_team=True)
    grants = {
        field.name: True
        for field in Team._meta.fields
        if isinstance(field, models.BooleanField)
        and field.name.startswith(('can_', 'is_'))
        and field.name != 'is_core_team'
    }
    core.update(
        **grants,
        all_events=True,
        all_teamshifts_roles=True,
        teamshifts_role='coordinator',
        limit_teamshifts_roles=[],
        force_hide_speaker_names=False,
        force_hide_speaker_emails=False,
        hide_exhibition_applicant_emails=False,
        hide_teamshifts_emails=False,
    )
    for relation in (Team.limit_events, Team.limit_tracks):
        relation.through.objects.using(core.db).filter(team_id__in=core.values('pk')).delete()


